public class Main {
    public static void main(String[] args) {
        int battery = 80;
        boolean hasBadge = true;
        boolean networkOnline = false;

        if (battery >= 50 && hasBadge) {
            System.out.println("Access granted");
            if (networkOnline) {
                System.out.println("Online route");
            } else {
                System.out.println("Backup route");
            }
        } else {
            System.out.println("Access denied");
        }
    }
}
